      "applies_to_keys": ["architectural_carrier_set", "design_ontology", "design_boundary_network"],
      "conditions": ["When defining schema, carrier family or typed public boundary under IACS policy."],
      "exceptions": ["With co_evolution_admissible(B), Ontology/IACS evidence/code/tests may develop together, but cannot self-ratify meaning and must reconcile before promotion/closure."],
      "grounding": [
        {
          "end_line": 1185,
          "quote": "The IACS is a realization projection of the Ontology.",
